#!/usr/bin/env bash
set -Eeuo pipefail
umask 077

OPERATOR_ROOT="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"
ENV_FILE="$OPERATOR_ROOT/operator.env"

die() {
    printf 'error: %s\n' "$*" >&2
    exit 1
}

[[ -f "$ENV_FILE" ]] || die "operator metadata is missing"
# operator.env contains deployment metadata only. Cryptographic identity and
# mint seed material are generated by this script inside the operator root.
# shellcheck disable=SC1090
source "$ENV_FILE"

: "${MEMBER_ID:?MEMBER_ID is required}"
: "${MEMBERS:?MEMBERS is required}"
: "${THRESHOLD:?THRESHOLD is required}"
: "${NETWORK:?NETWORK is required}"
: "${FEDERATION_AMOUNTS:?FEDERATION_AMOUNTS is required}"
: "${PUBLIC_MINT_URL:?PUBLIC_MINT_URL is required}"
: "${HTTP_ENABLED:?HTTP_ENABLED is required}"
: "${FEDERATION_API_URL:?FEDERATION_API_URL is required}"
: "${COORDINATOR_URL:?COORDINATOR_URL is required}"
: "${LISTEN_ADDR:?LISTEN_ADDR is required}"
: "${LISTEN_PORT:?LISTEN_PORT is required}"
: "${PROMETHEUS_PORT:?PROMETHEUS_PORT is required}"
: "${TMUX_SESSION:?TMUX_SESSION is required}"
: "${ESPLORA_URL:?ESPLORA_URL is required}"
: "${CHAIN_SOURCE_ID:?CHAIN_SOURCE_ID is required}"
: "${BARK_SERVER_ADDRESS:?BARK_SERVER_ADDRESS is required}"
: "${BARK_ESPLORA_URL:?BARK_ESPLORA_URL is required}"
: "${BARK_ARK_SERVER_PUBLIC_KEY:?BARK_ARK_SERVER_PUBLIC_KEY is required}"
: "${BARK_APPLICATION_KEY_EPOCH:?BARK_APPLICATION_KEY_EPOCH is required}"

MINTD="$OPERATOR_ROOT/bin/cdk-mintd"
RUNTIME_CONFIG="$OPERATOR_ROOT/runtime-config.toml"
WORK_DIR="$OPERATOR_ROOT/work"
RUNS_DIR="$OPERATOR_ROOT/runs"
BACKUP_DIR="$OPERATOR_ROOT/backups"
ACTION_TIMEOUT_SECS="${ACTION_TIMEOUT_SECS:-300}"
DKG_MAX_TICKS="${DKG_MAX_TICKS:-7200}"
DKG_RETRY_DELAY_MS="${DKG_RETRY_DELAY_MS:-250}"
DKG_CEREMONY_TIMEOUT_SECONDS="${DKG_CEREMONY_TIMEOUT_SECONDS:-1800}"

require_positive() {
    [[ "$2" =~ ^[1-9][0-9]*$ ]] || die "$1 must be a positive integer"
}

validate_environment() {
    local command
    for command in awk cmp curl grep jq openssl ps sed sha256sum tar tmux; do
        command -v "$command" >/dev/null 2>&1 \
            || die "required command not found: $command"
    done
    [[ -x "$MINTD" ]] || die "cdk-mintd is not installed"
    require_positive MEMBER_ID "$MEMBER_ID"
    require_positive MEMBERS "$MEMBERS"
    require_positive THRESHOLD "$THRESHOLD"
    require_positive LISTEN_PORT "$LISTEN_PORT"
    require_positive PROMETHEUS_PORT "$PROMETHEUS_PORT"
    require_positive ACTION_TIMEOUT_SECS "$ACTION_TIMEOUT_SECS"
    require_positive DKG_MAX_TICKS "$DKG_MAX_TICKS"
    require_positive DKG_RETRY_DELAY_MS "$DKG_RETRY_DELAY_MS"
    require_positive DKG_CEREMONY_TIMEOUT_SECONDS "$DKG_CEREMONY_TIMEOUT_SECONDS"
    require_positive BARK_APPLICATION_KEY_EPOCH "$BARK_APPLICATION_KEY_EPOCH"
    ((MEMBER_ID <= MEMBERS)) || die "MEMBER_ID exceeds member count"
    ((THRESHOLD <= MEMBERS)) || die "THRESHOLD exceeds member count"
    [[ "$NETWORK" =~ ^(bitcoin|testnet|signet|regtest)$ ]] \
        || die "NETWORK is unsupported"
    [[ "$FEDERATION_AMOUNTS" =~ ^[1-9][0-9]*(,[1-9][0-9]*)*$ ]] \
        || die "FEDERATION_AMOUNTS must be a comma-separated list of positive integers"
    [[ "$HTTP_ENABLED" == "true" || "$HTTP_ENABLED" == "false" ]] \
        || die "HTTP_ENABLED must be true or false"
    [[ "$FEDERATION_API_URL" =~ ^iroh://[a-z0-9]+$ ]] \
        || die "FEDERATION_API_URL must be a canonical Iroh endpoint URL"
    [[ "$COORDINATOR_URL" =~ ^iroh://[a-z0-9]+$ ]] \
        || die "COORDINATOR_URL must be a canonical Iroh endpoint URL"
    if [[ "$HTTP_ENABLED" == "false" ]]; then
        [[ "$PUBLIC_MINT_URL" == "$FEDERATION_API_URL" ]] \
            || die "an Iroh-only public mint URL must equal its federation endpoint"
    else
        [[ "$PUBLIC_MINT_URL" =~ ^https://[A-Za-z0-9._:/-]+$ ]] \
            || die "HTTP public mint URL must be credential-free HTTPS"
    fi
    [[ "$ESPLORA_URL" =~ ^https://[A-Za-z0-9._:/-]+$ ]] \
        || die "ESPLORA_URL must be a credential-free HTTPS URL"
    [[ "$BARK_SERVER_ADDRESS" =~ ^https://[A-Za-z0-9._:/-]+$ ]] \
        || die "BARK_SERVER_ADDRESS must be a credential-free HTTPS URL"
    [[ "$BARK_ESPLORA_URL" =~ ^https://[A-Za-z0-9._:/-]+$ ]] \
        || die "BARK_ESPLORA_URL must be a credential-free HTTPS URL"
    [[ "$BARK_ARK_SERVER_PUBLIC_KEY" =~ ^0[23][0-9a-fA-F]{64}$ ]] \
        || die "BARK_ARK_SERVER_PUBLIC_KEY must be a compressed secp256k1 public key"
    [[ "$CHAIN_SOURCE_ID" =~ ^[A-Za-z0-9._-]+$ ]] \
        || die "CHAIN_SOURCE_ID contains unsupported characters"
    [[ "$LISTEN_ADDR" == "127.0.0.1:$LISTEN_PORT" ]] \
        || die "LISTEN_ADDR must use the configured loopback port"
    [[ "$TMUX_SESSION" =~ ^[A-Za-z0-9._-]+$ ]] \
        || die "TMUX_SESSION contains unsupported characters"
}

validate_label() {
    [[ "$1" =~ ^[a-z][a-z0-9-]{0,31}$ ]] \
        || die "ceremony label contains unsupported characters"
}

ceremony_dir() {
    validate_label "$1"
    printf '%s/ceremonies/%s' "$OPERATOR_ROOT" "$1"
}

setup_config() {
    printf '%s/setup.json' "$(ceremony_dir "$1")"
}

setup_state_dir() {
    printf '%s/setup-state' "$(ceremony_dir "$1")"
}

setup_database() {
    if [[ "$1" == "active" ]]; then
        printf '%s/cdk-mintd.sqlite' "$WORK_DIR"
        return
    fi
    printf '%s/setup.sqlite' "$(ceremony_dir "$1")"
}

invitation_file() {
    printf '%s/incoming.invite' "$(ceremony_dir "$1")"
}

activated_public_config() {
    printf '%s/activated/federation-public.json' "$(setup_state_dir active)"
}

activated_private_config() {
    printf '%s/activated/federation-private.json' "$(setup_state_dir active)"
}

bark_policy_config() {
    printf '%s/bark-policy.json' "$(ceremony_dir "$1")"
}

write_bark_policy() {
    local label="$1" path
    path="$(bark_policy_config "$label")"
    cat >"$path" <<'EOF'
{
  "version": 1,
  "receive_base_fee_sat": 0,
  "receive_fee_ppm": 0,
  "maximum_outgoing_base_fee_sat": 20,
  "maximum_outgoing_fee_ppm": 5000,
  "minimum_incoming_cltv_delta": 18,
  "minimum_outgoing_cltv_delta": 18,
  "refresh_before_expiry_blocks": 72,
  "emergency_exit_before_expiry_blocks": 18,
  "receive_secret_retention_days": 30,
  "receive_anti_dos": "no_proof"
}
EOF
    chmod 600 "$path"
}

generate_runtime_config() {
    if [[ -f "$RUNTIME_CONFIG" ]]; then
        return
    fi
    [[ ! -e "$RUNTIME_CONFIG" ]] \
        || die "runtime config path exists but is not a regular file"
    local seed bark_operational_seed bark_receive_secret
    seed="$(openssl rand -hex 32)"
    bark_operational_seed="$(openssl rand -hex 64)"
    bark_receive_secret="$(openssl rand -hex 32)"
    mkdir -p "$WORK_DIR/frost-protocol"
    cat >"$RUNTIME_CONFIG" <<EOF
[info]
url = "$PUBLIC_MINT_URL"
http_enabled = $HTTP_ENABLED
listen_host = "127.0.0.1"
listen_port = $LISTEN_PORT
seed = "$seed"
enable_info_page = true

[iroh]
enabled = true
discovery = "n0"

[info.http_cache]
backend = "memory"
ttl = 60
tti = 60

[mint_info]
name = "Nocean multi-operator federation member $MEMBER_ID"
description = "Nocean invitation-based federation drill"

[prometheus]
enabled = true
address = "127.0.0.1"
port = $PROMETHEUS_PORT

[database]
engine = "sqlite"

[ln]
ln_backend = "federated-bark"
unit = "sat"
min_mint = 1
max_mint = 50000000
min_melt = 1
max_melt = 50000000

[onchain]
onchain_backend = "federated-bdk"
min_mint = 1
max_mint = 50000000
min_melt = 1
max_melt = 50000000

[federation]
enabled = true
public_config_path = "$(activated_public_config)"
private_config_path = "$(activated_private_config)"

[federation.peer_sync]
aleph_bft_active_unit_interval_ms = 200
aleph_bft_network_pump_max_messages_per_tick = 1

[federation.onchain_wallet]
enabled = true
network = "$NETWORK"
minimum_confirmations = 1
fee_policy_version = 1
chain_source_type = "esplora"
chain_source_scope = "shared"
chain_source_id = "$CHAIN_SOURCE_ID"
esplora_url = "$ESPLORA_URL"
esplora_parallel_requests = 1
request_timeout_secs = 30
esplora_max_retries = 3
sync_interval_secs = 15

[federation.bark]
enabled = true
network = "$NETWORK"
ark_server_public_key = "$BARK_ARK_SERVER_PUBLIC_KEY"
server_address = "$BARK_SERVER_ADDRESS"
esplora_url = "$BARK_ESPLORA_URL"
data_directory = "$WORK_DIR/federation-bark"
receive_secret_database_path = "$WORK_DIR/federation-bark/receive-secrets.redb"
frost_protocol_storage_root = "$WORK_DIR/frost-protocol"
operational_seed_hex = "$bark_operational_seed"
receive_secret_key_hex = "$bark_receive_secret"
create_if_missing = true
automatic_refresh = true
automatic_emergency_exit = false
EOF
    chmod 600 "$RUNTIME_CONFIG"
}

mintd_configured() {
    "$MINTD" --work-dir "$WORK_DIR" --config "$RUNTIME_CONFIG" "$@"
}

action_create() {
    local label="$1" dir
    ((MEMBER_ID == 1)) || die "only member 1 can create a ceremony"
    dir="$(ceremony_dir "$label")"
    [[ ! -e "$dir" ]] || die "ceremony directory already exists"
    mkdir -p "$dir"
    write_bark_policy "$label"
    generate_runtime_config
    mintd_configured federation setup create \
        --config "$(setup_config "$label")" \
        --state-dir "$(setup_state_dir "$label")" \
        --database "$(setup_database "$label")" \
        --members "$MEMBERS" \
        --threshold "$THRESHOLD" \
        --network "$NETWORK" \
        --public-mint-url "$PUBLIC_MINT_URL" \
        --federation-api-url "$FEDERATION_API_URL" \
        --coordinator-url "$COORDINATOR_URL" \
        --amounts "$FEDERATION_AMOUNTS" \
        --frost-bark-ark-server-public-key "$BARK_ARK_SERVER_PUBLIC_KEY" \
        --frost-bark-application-key-epoch "$BARK_APPLICATION_KEY_EPOCH" \
        --frost-bark-policy-config "$(bark_policy_config "$label")" \
        >"$dir/create.log"
}

action_join() {
    local label="$1" dir
    ((MEMBER_ID > 1)) || die "the creator cannot join its own ceremony"
    dir="$(ceremony_dir "$label")"
    [[ -f "$(invitation_file "$label")" ]] || die "protected invitation input is missing"
    generate_runtime_config
    mintd_configured federation setup join \
        --invitation-file "$(invitation_file "$label")" \
        --config "$(setup_config "$label")" \
        --state-dir "$(setup_state_dir "$label")" \
        --database "$(setup_database "$label")" \
        --public-mint-url "$PUBLIC_MINT_URL" \
        --federation-api-url "$FEDERATION_API_URL" \
        >"$dir/join.log"
}

action_propose() {
    local label="$1" dir
    dir="$(ceremony_dir "$label")"
    mintd_configured federation setup propose \
        --config "$(setup_config "$label")" \
        >"$dir/propose.log"
}

action_propose_expect_failure() {
    local label="$1" dir
    dir="$(ceremony_dir "$label")"
    if mintd_configured federation setup propose \
        --config "$(setup_config "$label")" \
        >"$dir/expected-propose-failure.log" 2>&1; then
        die "incomplete setup unexpectedly produced a proposal"
    fi
}

action_review() {
    local label="$1" dir
    dir="$(ceremony_dir "$label")"
    mintd_configured federation setup review \
        --config "$(setup_config "$label")" \
        --json >"$dir/review.json"
}

action_approve() {
    local label="$1" proposal_hash="$2" dir
    [[ "$proposal_hash" =~ ^[0-9a-f]{64}$ ]] || die "proposal hash is invalid"
    dir="$(ceremony_dir "$label")"
    mintd_configured federation setup approve \
        --config "$(setup_config "$label")" \
        --proposal-hash "$proposal_hash" \
        >"$dir/approve.log"
}

action_certified_status() {
    local label="$1" dir
    dir="$(ceremony_dir "$label")"
    mintd_configured federation setup status \
        --config "$(setup_config "$label")" \
        --json >"$dir/certified-status.json"
    [[ "$(jq -r '.participant_phase' "$dir/certified-status.json")" == "certified" ]] \
        || die "certified manifest is not locally persisted"
}

action_activate() {
    local label="$1" dir
    [[ "$label" == "active" ]] || die "only the active ceremony can be activated"
    dir="$(ceremony_dir "$label")"
    mintd_configured federation setup activate \
        --config "$(setup_config "$label")" \
        >"$dir/activation.env" \
        2>"$dir/activation-guidance.log"
}

action_backup_restore() {
    local label="$1" pass_file encrypted restore_dir
    [[ "$label" == "active" ]] || die "only active operator state can be backed up"
    [[ -f "$(activated_private_config)" ]] || die "activated private config is missing"
    mkdir -p "$BACKUP_DIR"
    pass_file="$BACKUP_DIR/operator-backup.pass"
    encrypted="$BACKUP_DIR/operator-state.tar.gz.enc"
    restore_dir="$BACKUP_DIR/restore-check"
    openssl rand -base64 48 >"$pass_file"
    chmod 600 "$pass_file"
    tar -C "$OPERATOR_ROOT" -czf - \
        ceremonies/active runtime-config.toml work \
        | openssl enc -aes-256-cbc -pbkdf2 -salt \
            -pass "file:$pass_file" -out "$encrypted"
    chmod 600 "$encrypted"
    rm -rf -- "$restore_dir"
    mkdir -p "$restore_dir"
    openssl enc -d -aes-256-cbc -pbkdf2 \
        -pass "file:$pass_file" -in "$encrypted" \
        | tar -C "$restore_dir" -xzf -
    cmp -s "$(setup_config active)" \
        "$restore_dir/ceremonies/active/setup.json" \
        || die "restored setup config differs"
    cmp -s "$(activated_private_config)" \
        "$restore_dir/ceremonies/active/setup-state/activated/federation-private.json" \
        || die "restored private config differs"
    cmp -s "$RUNTIME_CONFIG" "$restore_dir/runtime-config.toml" \
        || die "restored runtime config differs"
    cmp -s "$WORK_DIR/cdk-mintd.sqlite" "$restore_dir/work/cdk-mintd.sqlite" \
        || die "restored runtime database differs"
    jq -n \
        --arg cipher "aes-256-cbc-pbkdf2" \
        --argjson member "$MEMBER_ID" \
        '{result: "passed", member: $member, cipher: $cipher, local_restore: true}' \
        >"$BACKUP_DIR/restore-report.json"
}

run_action() {
    local label="$1" action="$2" argument="${3:-}" status_file exit_code
    validate_label "$label"
    [[ "$action" =~ ^[a-z][a-z-]{0,31}$ ]] || die "action contains unsupported characters"
    status_file="$RUNS_DIR/$label-$action.status"
    mkdir -p "$RUNS_DIR"
    rm -f -- "$status_file"
    trap 'exit_code=$?; printf "%s\n" "$exit_code" >"$status_file"' EXIT
    set +e
    case "$action" in
        create) action_create "$label" ;;
        join) action_join "$label" ;;
        propose) action_propose "$label" ;;
        propose-expect-failure) action_propose_expect_failure "$label" ;;
        review) action_review "$label" ;;
        approve) action_approve "$label" "$argument" ;;
        certified-status) action_certified_status "$label" ;;
        activate) action_activate "$label" ;;
        backup-restore) action_backup_restore "$label" ;;
        *) printf 'unsupported operator action\n' >&2; false ;;
    esac
    exit_code=$?
    set -e
    printf '%s\n' "$exit_code" >"$status_file"
    trap - EXIT
    return "$exit_code"
}

session_init() {
    if tmux has-session -t "$TMUX_SESSION" 2>/dev/null; then
        die "operator tmux session already exists"
    fi
    local command
    printf -v command 'cd %q && exec bash scripts/nocean_federation_operator.sh idle' \
        "$OPERATOR_ROOT"
    tmux new-session -d -s "$TMUX_SESSION" -n operator -c "$OPERATOR_ROOT" "$command"
    tmux set-option -t "$TMUX_SESSION" remain-on-exit on
    tmux select-pane -t "$TMUX_SESSION:operator.0" -T "operator-$MEMBER_ID"
}

idle() {
    while true; do
        sleep 3600
    done
}

session_run_wait() {
    local label="$1" action="$2" argument="${3:-}" status_file command deadline code
    validate_label "$label"
    [[ "$action" =~ ^[a-z][a-z-]{0,31}$ ]] || die "action contains unsupported characters"
    [[ "$argument" =~ ^[A-Za-z0-9._:-]*$ ]] || die "action argument contains unsupported characters"
    tmux has-session -t "$TMUX_SESSION" 2>/dev/null || die "operator tmux session is missing"
    status_file="$RUNS_DIR/$label-$action.status"
    mkdir -p "$RUNS_DIR"
    rm -f -- "$status_file"
    printf -v command 'cd %q && exec bash scripts/nocean_federation_operator.sh run-action %q %q %q' \
        "$OPERATOR_ROOT" "$label" "$action" "$argument"
    tmux respawn-pane -k -t "$TMUX_SESSION:operator.0" "$command"
    tmux select-pane -t "$TMUX_SESSION:operator.0" -T "operator-$MEMBER_ID-$action"
    deadline=$((SECONDS + ACTION_TIMEOUT_SECS))
    while ((SECONDS < deadline)); do
        if [[ -f "$status_file" ]]; then
            code="$(sed -n '1p' "$status_file")"
            [[ "$code" =~ ^[0-9]+$ ]] || die "operator action status is invalid"
            ((code == 0)) || die "operator action failed: $action"
            return 0
        fi
        sleep 0.25
    done
    die "operator action timed out: $action"
}

service_start() {
    local label="$1" mode="$2" command
    validate_label "$label"
    tmux has-session -t "$TMUX_SESSION" 2>/dev/null || die "operator tmux session is missing"
    case "$mode" in
        setup)
            printf -v command \
                'cd %q && exec env RUST_LOG=info %q --work-dir %q --config %q federation setup serve --config %q --listen %q --dkg-max-ticks %q --dkg-retry-delay-ms %q --dkg-ceremony-timeout-seconds %q >>%q 2>&1' \
                "$OPERATOR_ROOT" "$MINTD" "$WORK_DIR" "$RUNTIME_CONFIG" \
                "$(setup_config "$label")" "$LISTEN_ADDR" \
                "$DKG_MAX_TICKS" "$DKG_RETRY_DELAY_MS" "$DKG_CEREMONY_TIMEOUT_SECONDS" \
                "$(ceremony_dir "$label")/setup-service.log"
            ;;
        runtime)
            [[ "$label" == "active" ]] || die "runtime requires the active ceremony"
            printf -v command \
                'cd %q && exec env RUST_LOG=info CDK_MINTD_FEDERATION_OPERATION_SUBMISSION_TIMEOUT_SECS=180 %q --work-dir %q --config %q' \
                "$OPERATOR_ROOT" "$MINTD" "$WORK_DIR" "$RUNTIME_CONFIG"
            ;;
        *) die "service mode must be setup or runtime" ;;
    esac
    if tmux list-windows -t "$TMUX_SESSION" -F '#{window_name}' | grep -Fxq service; then
        tmux respawn-pane -k -t "$TMUX_SESSION:service.0" "$command"
    else
        tmux new-window -d -t "$TMUX_SESSION" -n service -c "$OPERATOR_ROOT" "$command"
    fi
    tmux select-pane -t "$TMUX_SESSION:service.0" -T "member-$MEMBER_ID-$mode"
}

service_stop() {
    tmux has-session -t "$TMUX_SESSION" 2>/dev/null || die "operator tmux session is missing"
    if tmux list-windows -t "$TMUX_SESSION" -F '#{window_name}' | grep -Fxq service; then
        tmux kill-window -t "$TMUX_SESSION:service"
    fi
}

service_stopped() {
    tmux has-session -t "$TMUX_SESSION" 2>/dev/null || die "operator tmux session is missing"
    if tmux list-windows -t "$TMUX_SESSION" -F '#{window_name}' | grep -Fxq service; then
        die "operator service window is still running"
    fi
}

status_json() {
    local label="$1"
    validate_label "$label"
    mintd_configured federation setup status --config "$(setup_config "$label")" --json
}

public_config_hash() {
    [[ -f "$(activated_public_config)" ]] || die "activated public config is missing"
    sha256sum "$(activated_public_config)" | awk '{print $1}'
}

proposal_hash() {
    local label="$1"
    validate_label "$label"
    sed -n 's/^proposal_hash: //p' "$(ceremony_dir "$label")/propose.log"
}

review_proposal_hash() {
    local label="$1"
    validate_label "$label"
    jq -r '.proposal_hash' "$(ceremony_dir "$label")/review.json"
}

runtime_status() {
    mintd_configured federation status \
        --public-config "$(activated_public_config)" \
        --private-config "$(activated_private_config)" \
        --require-ready \
        --require-converged \
        --max-operation-lag 0 \
        --require-no-digest-alerts \
        --require-no-payment-observation-alerts \
        --require-no-invalid-operation-alerts
}

http_listener_disabled() {
    [[ "$HTTP_ENABLED" == "false" ]] \
        || die "HTTP listener check requires HTTP_ENABLED=false"
    if curl --silent --output /dev/null --max-time 2 --noproxy '*' \
        "http://$LISTEN_ADDR/v1/info"; then
        die "configured HTTP listener is unexpectedly reachable"
    fi
}

service_metrics() {
    local pid sample
    tmux has-session -t "$TMUX_SESSION" 2>/dev/null || die "operator tmux session is missing"
    tmux list-windows -t "$TMUX_SESSION" -F '#{window_name}' | grep -Fxq service \
        || die "service window is missing"
    pid="$(tmux display-message -p -t "$TMUX_SESSION:service.0" '#{pane_pid}')"
    sample="$(ps -p "$pid" -o time= -o rss= 2>/dev/null || true)"
    [[ -n "$sample" ]] || die "service process metrics are unavailable"
    awk -v member="$MEMBER_ID" 'NF { print member "," $1 "," $2; exit }' <<<"$sample"
}

session_layout() {
    tmux list-windows -t "$TMUX_SESSION" -F '#{session_name},#{window_name},#{pane_title},#{pane_dead}'
}

validate_environment
case "${1:-}" in
    validate) ;;
    idle) idle ;;
    session-init) session_init ;;
    session-run-wait) session_run_wait "${2:?label required}" "${3:?action required}" "${4:-}" ;;
    service-start) service_start "${2:?label required}" "${3:?mode required}" ;;
    service-stop) service_stop ;;
    service-stopped) service_stopped ;;
    run-action) run_action "${2:?label required}" "${3:?action required}" "${4:-}" ;;
    status-json) status_json "${2:?label required}" ;;
    proposal-hash) proposal_hash "${2:?label required}" ;;
    review-proposal-hash) review_proposal_hash "${2:?label required}" ;;
    public-config-hash) public_config_hash ;;
    runtime-status) runtime_status ;;
    http-listener-disabled) http_listener_disabled ;;
    service-metrics) service_metrics ;;
    session-layout) session_layout ;;
    *) die "usage: $0 {validate|idle|session-init|session-run-wait|service-start|service-stop|service-stopped|status-json|proposal-hash|review-proposal-hash|public-config-hash|runtime-status|http-listener-disabled|service-metrics|session-layout}" ;;
esac
